const requests = $('Firebase - Get Recipe Requests').item.json ?? {};
const quota = $('Firebase - Get Quota').item.json ?? {};
const now = new Date();
const requestCutoff = new Date(now);

requestCutoff.setUTCDate(now.getUTCDate() - 7);

const firebaseUpdate = {
  ...buildRequestDeletes(requests, requestCutoff.getTime()),
  ...buildQuotaDeletes(quota, toDayKey(requestCutoff)),
};

return [{ json: { firebaseUpdate } }];

/** Creates delete updates for safely finished old requests. */
function buildRequestDeletes(requests, cutoffTime) {
  return Object.entries(requests).reduce((updates, [requestId, request]) => {
    if (shouldDeleteRequest(request, cutoffTime)) {
      updates[`recipeRequests/${requestId}`] = null;
    }

    return updates;
  }, {});
}

/** Checks whether one request is finished and older than seven days. */
function shouldDeleteRequest(request, cutoffTime) {
  const finished = ['completed', 'failed', 'quotaExceeded'].includes(request?.status);
  const timestamp = Date.parse(request?.updatedAt ?? request?.createdAt ?? '');

  return finished && Number.isFinite(timestamp) && timestamp < cutoffTime;
}

/** Creates delete updates for quota days older than the retained period. */
function buildQuotaDeletes(quota, cutoffDayKey) {
  const updates = {};
  addQuotaDeletes(updates, quota.dailyByIp, 'quota/dailyByIp', cutoffDayKey);
  addQuotaDeletes(updates, quota.dailySystem, 'quota/dailySystem', cutoffDayKey);

  return updates;
}

/** Adds deletion paths for old UTC quota day keys. */
function addQuotaDeletes(updates, records, path, cutoffDayKey) {
  Object.keys(records ?? {})
    .filter((dayKey) => dayKey < cutoffDayKey)
    .forEach((dayKey) => {
      updates[`${path}/${dayKey}`] = null;
    });
}

/** Converts a date into the same UTC key format as the main workflow. */
function toDayKey(date) {
  return date.toISOString().slice(0, 10);
}
